class SumOfDistancesInfo(InfoStrategy):
    """
    Each revealed cell shows the SUM of Manhattan distances to all adjacent mines,
    rather than the count. A cell with one far-diagonal mine (distance 2) shows 2;
    a cell with two orthogonal mines (distance 1 each) shows 2 as well — same
    display, different configurations. Players/solvers must triangulate across
    multiple cells to reconstruct mine positions. Solvable but requires richer
    constraint reasoning than vanilla minesweeper.
    """

    def encode(self, board, r, c):
        total = 0
        for nr, nc in board.neighbors(r, c):
            if board.grid[nr][nc].is_mine:
                total += abs(nr - r) + abs(nc - c)
        return str(total) if total > 0 else ""

