class SumOfDistancesMinesweeperAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def clue_value(self, game, grid, r, c):
        cell = game.get_cell(r, c)
        if not cell.is_revealed:
            return None
        raw = cell.adjacent_mines
        if raw == 0:
            return 0
        neighbors = game.board.neighbors(r, c)
        if not neighbors:
            return 0
        total_dist = 0
        count = 0
        for nr, nc in neighbors:
            d = abs(nr - r) + abs(nc - c)
            total_dist += d
            count += 1
        avg_dist = total_dist / count if count > 0 else 1.0
        estimated = raw / avg_dist
        return max(1, round(estimated))

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        adjusted = dict(prob_map)

        revealed_cells = []
        for r in range(rows):
            for c in range(cols):
                cell = game.get_cell(r, c)
                if cell.is_revealed and cell.adjacent_mines > 0:
                    revealed_cells.append((r, c))

        for r, c in revealed_cells:
            cell = game.get_cell(r, c)
            sum_dist_clue = cell.adjacent_mines
            neighbors = game.board.neighbors(r, c)
            unknown_neighbors = [
                (nr, nc) for nr, nc in neighbors
                if not game.get_cell(nr, nc).is_revealed and not game.get_cell(nr, nc).is_flagged
            ]
            flagged_neighbors = [
                (nr, nc) for nr, nc in neighbors
                if game.get_cell(nr, nc).is_flagged
            ]
            known_mine_neighbors = [
                (nr, nc) for nr, nc in neighbors
                if (nr, nc) in mine_set
            ]

            flagged_dist_sum = sum(abs(nr - r) + abs(nc - c) for nr, nc in flagged_neighbors)
            known_dist_sum = sum(abs(nr - r) + abs(nc - c) for nr, nc in known_mine_neighbors)
            accounted = flagged_dist_sum + known_dist_sum
            remaining_sum = sum_dist_clue - accounted

            if remaining_sum <= 0 or not unknown_neighbors:
                continue

            dist_weights = {}
            total_weight = 0
            for nr, nc in unknown_neighbors:
                d = abs(nr - r) + abs(nc - c)
                dist_weights[(nr, nc)] = d
                total_weight += d

            if total_weight <= 0:
                continue

            for pos in unknown_neighbors:
                if pos not in adjusted:
                    continue
                d = dist_weights[pos]
                weight_fraction = d / total_weight
                base_prob = adjusted[pos]
                if remaining_sum > 0:
                    distance_signal = weight_fraction * (remaining_sum / max(remaining_sum, total_weight))
                    blended = 0.6 * base_prob + 0.4 * min(1.0, distance_signal)
                    adjusted[pos] = blended

        return adjusted

class ChainReactionAwarePAFGAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        base_prob = prob_map.get(pos, Fraction(1, 2))

        unrevealed_neighbors = []
        for nr, nc in game.board.neighbors(r, c):
            cell = grid[nr][nc]
            if not cell.is_revealed and not cell.is_flagged:
                unrevealed_neighbors.append((nr, nc))

        visited = set()
        cluster_size = 0
        queue = deque()
        for nb in unrevealed_neighbors:
            if nb not in visited:
                visited.add(nb)
                nb_prob = prob_map.get(nb, Fraction(1, 2))
                if nb_prob > Fraction(1, 3):
                    queue.append(nb)
                    cluster_size += 1

        frontier = list(queue)
        expanded = set(frontier)
        depth = 0
        while frontier and depth < 3:
            next_frontier = []
            for fr, fc in frontier:
                for nr2, nc2 in game.board.neighbors(fr, fc):
                    if (nr2, nc2) not in expanded:
                        cell2 = grid[nr2][nc2]
                        if not cell2.is_revealed and not cell2.is_flagged:
                            nb_prob2 = prob_map.get((nr2, nc2), Fraction(1, 2))
                            if nb_prob2 > Fraction(1, 3):
                                expanded.add((nr2, nc2))
                                next_frontier.append((nr2, nc2))
                                cluster_size += 1
            frontier = next_frontier
            depth += 1

        cluster_penalty = Fraction(cluster_size, max(cluster_size + 1, 1))
        combined_risk = base_prob + (Fraction(1, 4) * cluster_penalty * base_prob)

        return (combined_risk, cluster_size, self._rng.random())

class NoisyCountMinesweeperAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def clue_value(self, game, grid, r, c):
        cell = grid[r][c]
        if not cell.is_revealed or cell.is_mine:
            return None
        raw = cell.adjacent_mines
        return raw

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        total_cells = rows * cols
        revealed_count = sum(1 for r in range(rows) for c in range(cols) if grid[r][c].is_revealed)
        flagged_count = sum(1 for r in range(rows) for c in range(cols) if grid[r][c].is_flagged)
        unrevealed_count = total_cells - revealed_count - flagged_count
        config = game.get_config()
        total_mines = config.mine_count
        known_mines = len(mine_set)
        remaining_mines = total_mines - known_mines - flagged_count
        if unrevealed_count <= 0:
            return prob_map
        base_prob = max(0.0, min(1.0, remaining_mines / max(unrevealed_count, 1)))
        noise_bias = 0.08
        adjusted = {}
        for pos, p in prob_map.items():
            r, c = pos
            if grid[r][c].is_revealed or grid[r][c].is_flagged:
                adjusted[pos] = p
                continue
            if p < 1e-9:
                new_p = min(noise_bias, base_prob)
            elif p > 1.0 - 1e-9:
                new_p = p
            else:
                new_p = min(1.0, p + noise_bias * (1.0 - p))
            adjusted[pos] = new_p
        return adjusted

class CheckerboardParityPAFGAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)
        self._first_parity = None

    def opening_action(self, game, grid, rows, cols):
        mid_r, mid_c = rows // 2, cols // 2
        self._first_parity = (mid_r + mid_c) % 2
        return ("reveal", mid_r, mid_c)

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0

        revealed_clues = {}
        for r in range(rows):
            for c in range(cols):
                cell = game.get_cell(r, c)
                if cell.is_revealed and not cell.is_mine and cell.adjacent_mines > 0:
                    revealed_clues[(r, c)] = cell.adjacent_mines

        for (r, c), clue in revealed_clues.items():
            cell_parity = (r + c) % 2
            neighbors = [(nr, nc) for nr, nc in game.board.neighbors(r, c)
                         if 0 <= nr < rows and 0 <= nc < cols]
            same_parity_unrevealed = [(nr, nc) for nr, nc in neighbors
                                      if not game.get_cell(nr, nc).is_revealed
                                      and not game.get_cell(nr, nc).is_flagged
                                      and (nr + nc) % 2 == cell_parity]
            opposite_parity_unrevealed = [(nr, nc) for nr, nc in neighbors
                                          if not game.get_cell(nr, nc).is_revealed
                                          and not game.get_cell(nr, nc).is_flagged
                                          and (nr + nc) % 2 != cell_parity]
            flagged_count = sum(1 for nr, nc in neighbors
                                if game.get_cell(nr, nc).is_flagged)
            remaining_mines = clue - flagged_count

            if remaining_mines < 0:
                continue

            all_unrevealed = same_parity_unrevealed + opposite_parity_unrevealed
            if len(all_unrevealed) == 0:
                continue

            if remaining_mines == 0:
                for pos in all_unrevealed:
                    if pos in prob_map and prob_map[pos] > Fraction(0):
                        prob_map[pos] = Fraction(0)

            if remaining_mines == len(all_unrevealed):
                for pos in all_unrevealed:
                    if pos in prob_map and prob_map[pos] < Fraction(1):
                        prob_map[pos] = Fraction(1)

            if len(same_parity_unrevealed) > 0 and remaining_mines == len(opposite_parity_unrevealed):
                for pos in same_parity_unrevealed:
                    if pos in prob_map and prob_map[pos] > Fraction(0):
                        prob_map[pos] = Fraction(0)

            if len(opposite_parity_unrevealed) > 0 and remaining_mines == len(same_parity_unrevealed) + len(opposite_parity_unrevealed):
                for pos in same_parity_unrevealed + opposite_parity_unrevealed:
                    if pos in prob_map and prob_map[pos] < Fraction(1):
                        prob_map[pos] = Fraction(1)

        return prob_map

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        prob = prob_map.get(pos, Fraction(1, 2))
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0

        revealed_neighbors = sum(1 for nr, nc in game.board.neighbors(r, c)
                                 if 0 <= nr < rows and 0 <= nc < cols
                                 and game.get_cell(nr, nc).is_revealed
                                 and not game.get_cell(nr, nc).is_mine)

        cascade_bonus = Fraction(0)
        if self._first_parity is not None and (r + c) % 2 == self._first_parity:
            cascade_bonus = Fraction(1, 10)

        constraint_score = Fraction(revealed_neighbors, 8)
        return (prob, -constraint_score - cascade_bonus, self._rng.random())

