class GravitationalMines(MineBehavior):
    """
    After each action, every unflagged mine is attracted toward the nearest
    revealed safe cell: it moves one step closer (choosing the neighbor that
    minimizes Chebyshev distance to that attractor) if that neighbor is
    unrevealed, unflagged, and not already a mine. Flagging a mine pins it
    in place, making flag-placement a strategic tool to freeze dangerous mines
    near revealed regions. Skilled solvers can exploit the predictable drift
    direction to anticipate which cells become newly dangerous, while random
    play walks blindly into mines that have crept closer.
    """

    def _chebyshev(self, r1, c1, r2, c2):
        return max(abs(r1 - r2), abs(c1 - c2))

    def on_post_action(self, board, game, action):
        # Collect all revealed safe cells as potential attractors
        revealed_safe = [
            (r, c)
            for r in range(board.config.rows)
            for c in range(board.config.cols)
            if board.grid[r][c].is_revealed and not board.grid[r][c].is_mine
        ]
        if not revealed_safe:
            return

        # Snapshot mine positions so moves this tick don't cascade
        mines = [
            (r, c)
            for r in range(board.config.rows)
            for c in range(board.config.cols)
            if board.grid[r][c].is_mine and not board.grid[r][c].is_flagged
        ]

        moved = False
        for (mr, mc) in mines:
            # Find the nearest revealed safe cell to this mine
            best_dist = None
            best_target = None
            for (sr, sc) in revealed_safe:
                d = self._chebyshev(mr, mc, sr, sc)
                if best_dist is None or d < best_dist:
                    best_dist = d
                    best_target = (sr, sc)

            if best_target is None or best_dist == 0:
                continue

            tr, tc = best_target

            # Among valid neighbors, pick the one that minimizes distance to target
            candidates = [
                (nr, nc) for nr, nc in board.neighbors(mr, mc)
                if not board.grid[nr][nc].is_revealed
                and not board.grid[nr][nc].is_flagged
                and not board.grid[nr][nc].is_mine
            ]
            if not candidates:
                continue

            # Sort by distance to attractor, break ties randomly
            self._rng.shuffle(candidates)
            candidates.sort(key=lambda pos: self._chebyshev(pos[0], pos[1], tr, tc))

            best_neighbor = candidates[0]
            new_dist = self._chebyshev(best_neighbor[0], best_neighbor[1], tr, tc)

            # Only move if it actually gets closer
            if new_dist < best_dist:
                if board.move_mine((mr, mc), best_neighbor):
                    moved = True

        if moved:
            board.recompute_adjacency()

