class GravitationalMinesPAFGAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def action_priority(self, game, grid, rows, cols):
        return "flag-first"

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0

        revealed_safe = set()
        for r in range(rows):
            for c in range(cols):
                cell = game.get_cell(r, c)
                if cell.is_revealed and not cell.is_mine:
                    revealed_safe.add((r, c))

        danger_cells = set()
        for (r, c) in revealed_safe:
            for (nr, nc) in game.board.neighbors(r, c):
                ncell = game.get_cell(nr, nc)
                if not ncell.is_revealed and not ncell.is_flagged:
                    danger_cells.add((nr, nc))

        gravity_pull = {}
        for (ur, uc) in danger_cells:
            if (ur, uc) in prob_map:
                best_dist = None
                for (sr, sc) in revealed_safe:
                    d = max(abs(ur - sr), abs(uc - sc))
                    if best_dist is None or d < best_dist:
                        best_dist = d
                if best_dist is not None and best_dist <= 2:
                    gravity_pull[(ur, uc)] = best_dist

        new_prob_map = dict(prob_map)
        total_mines = game.get_config().mine_count
        total_cells = rows * cols
        flagged_count = sum(
            1 for r in range(rows) for c in range(cols)
            if game.get_cell(r, c).is_flagged
        )
        remaining_mines = total_mines - flagged_count
        unrevealed_count = sum(
            1 for r in range(rows) for c in range(cols)
            if not game.get_cell(r, c).is_revealed and not game.get_cell(r, c).is_flagged
        )
        base_prob = Fraction(remaining_mines, max(unrevealed_count, 1))

        for pos in gravity_pull:
            if pos in new_prob_map:
                dist = gravity_pull[pos]
                if dist == 1:
                    boost = Fraction(1, 3)
                else:
                    boost = Fraction(1, 6)
                old = new_prob_map[pos]
                boosted = old + boost * (1 - old)
                if boosted > Fraction(99, 100):
                    boosted = Fraction(99, 100)
                new_prob_map[pos] = boosted

        return new_prob_map

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        prob = prob_map.get(pos, Fraction(1, 2))

        revealed_safe_neighbors = 0
        for (nr, nc) in game.board.neighbors(r, c):
            ncell = game.get_cell(nr, nc)
            if ncell.is_revealed and not ncell.is_mine:
                revealed_safe_neighbors += 1

        danger_bonus = Fraction(revealed_safe_neighbors, 10)
        adjusted = prob + danger_bonus
        return (adjusted, self._rng.random())

class SectorClueAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def clue_value(self, game, grid, r, c):
        cell = game.get_cell(r, c)
        if not cell.is_revealed:
            return None
        if cell.is_mine:
            return None
        return cell.adjacent_mines

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        config = game.get_config()
        total_mines = config.mine_count

        revealed_non_mine = 0
        for r in range(rows):
            for c in range(cols):
                cell = game.get_cell(r, c)
                if cell.is_revealed and not cell.is_mine:
                    revealed_non_mine += 1

        flagged_count = sum(1 for (r, c) in mine_set)
        known_mine_positions = set(mine_set)

        for r in range(rows):
            for c in range(cols):
                cell = game.get_cell(r, c)
                if cell.is_revealed and not cell.is_mine:
                    raw = cell.adjacent_mines
                    if raw == 0:
                        for nr, nc in game.board.neighbors(r, c):
                            ncell = game.get_cell(nr, nc)
                            if not ncell.is_revealed and (nr, nc) not in known_mine_positions:
                                prob_map[(nr, nc)] = 0.0

        unrevealed = [(r, c) for r in range(rows) for c in range(cols)
                      if not game.get_cell(r, c).is_revealed and (r, c) not in known_mine_positions]

        if unrevealed:
            already_accounted = sum(1 for pos in known_mine_positions)
            remaining_mines = total_mines - already_accounted
            if remaining_mines < 0:
                remaining_mines = 0
            base_prob = remaining_mines / len(unrevealed) if len(unrevealed) > 0 else 0.0
            for pos in unrevealed:
                if pos not in prob_map:
                    prob_map[pos] = base_prob

        return prob_map

