class RippleReveal(RevealStrategy):
    """
    Cascade reveal with a twist: each revealed zero-cell also reveals a 'ripple ring'
    of cells at exactly distance 2 (by Chebyshev/Moore steps), skipping distance-1
    neighbors. This creates gaps in revealed information — border cells around zeros
    are NOT auto-revealed, so solvers must deduce mine positions from discontiguous
    clue sets while random play cannot exploit the partial information.
    The distance-1 neighbors of zero cells remain hidden unless directly clicked,
    creating rings of unknown cells between revealed regions.
    """

    def reveal(self, board: Board, r: int, c: int) -> list[tuple[int, int]]:
        cell = board.grid[r][c]
        # Non-zero cells: reveal only the clicked cell
        if cell.is_mine or cell.is_flagged:
            return []
        if cell.adjacent_mines > 0:
            cell.is_revealed = True
            return [(r, c)]

        # BFS over zero-cells only; for each zero cell, also reveal distance-2 ring
        queue = deque([(r, c)])
        visited_zero = {(r, c)}
        revealed = []

        while queue:
            cr, cc = queue.popleft()
            curr = board.grid[cr][cc]
            if curr.is_mine or curr.is_flagged:
                continue
            if not curr.is_revealed:
                curr.is_revealed = True
                revealed.append((cr, cc))

            if curr.adjacent_mines == 0:
                # Find distance-2 cells (Chebyshev distance == 2)
                for dr in range(-2, 3):
                    for dc in range(-2, 3):
                        if max(abs(dr), abs(dc)) != 2:
                            continue
                        nr, nc = cr + dr, cc + dc
                        if not board.in_bounds(nr, nc):
                            continue
                        ncell = board.grid[nr][nc]
                        if ncell.is_mine or ncell.is_flagged or ncell.is_revealed:
                            continue
                        ncell.is_revealed = True
                        revealed.append((nr, nc))
                        # If this distance-2 cell is also zero, add to BFS
                        if ncell.adjacent_mines == 0 and (nr, nc) not in visited_zero:
                            visited_zero.add((nr, nc))
                            queue.append((nr, nc))

        return revealed

