class RippleRevealPAFGAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def _gap_ring(self, game, r, c, rows, cols):
        result = []
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    result.append((nr, nc))
        return result

    def _dist2_ring(self, game, r, c, rows, cols):
        result = []
        for dr in range(-2, 3):
            for dc in range(-2, 3):
                if max(abs(dr), abs(dc)) != 2:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    result.append((nr, nc))
        return result

    def clue_value(self, game, grid, r, c):
        cell = grid[r][c]
        if not cell.is_revealed or cell.is_mine:
            return None
        rows = game.get_config().rows
        cols = game.get_config().cols
        base = cell.adjacent_mines
        gap_neighbors = self._gap_ring(game, r, c, rows, cols)
        flagged_in_gap = sum(1 for nr, nc in gap_neighbors if grid[nr][nc].is_flagged)
        return base - flagged_in_gap

    def neighbor_positions(self, game, r, c, rows, cols):
        dist2 = self._dist2_ring(game, r, c, rows, cols)
        gap = self._gap_ring(game, r, c, rows, cols)
        combined = set(dist2) | set(gap)
        return list(combined)

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = game.get_config().rows
        cols = game.get_config().cols
        total_cells = rows * cols
        revealed_count = sum(1 for rr in range(rows) for cc in range(cols) if grid[rr][cc].is_revealed)
        hidden_count = total_cells - revealed_count
        mine_count = game.get_config().mine_count
        known_mines = len(mine_set)
        remaining_mines = mine_count - known_mines
        if hidden_count <= 0:
            return prob_map
        base_prob = remaining_mines / hidden_count

        gap_cells = set()
        for rr in range(rows):
            for cc in range(cols):
                cell = grid[rr][cc]
                if not cell.is_revealed or cell.is_mine or cell.adjacent_mines == 0:
                    continue
                for nr, nc in self._gap_ring(game, rr, cc, rows, cols):
                    nc_cell = grid[nr][nc]
                    if not nc_cell.is_revealed and not nc_cell.is_flagged:
                        gap_cells.add((nr, nc))

        new_prob_map = dict(prob_map)
        for pos in gap_cells:
            if pos not in mine_set:
                current = new_prob_map.get(pos, base_prob)
                new_prob_map[pos] = min(1.0, current * 1.3)
        return new_prob_map

