class ProgressiveZoneWin(WinCondition):
    """
    The board is divided into a 3x3 grid of zones. The player must fully
    clear (reveal all safe cells) each zone before moving to the next.
    Zones unlock in sequence: center first, then the four cardinal zones,
    then the four corner zones. If the player reveals a cell in a locked
    zone, they lose immediately. This forces the skilled solver to
    methodically deduce mine positions zone by zone, while random play
    quickly clicks into locked zones and loses.
    """

    def __init__(self, seed=None):
        super().__init__(seed)
        self._zone_order = None
        self._unlocked_up_to = 0  # index into zone_order: zones 0..this are unlocked

    def _build_zone_order(self, rows, cols):
        # 3x3 grid of zones; each zone is a (zone_row, zone_col) index
        # Order: center (1,1), cardinals (0,1),(1,0),(1,2),(2,1), corners (0,0),(0,2),(2,0),(2,2)
        order = [
            (1, 1),
            (0, 1), (1, 0), (1, 2), (2, 1),
            (0, 0), (0, 2), (2, 0), (2, 2),
        ]
        return order

    def _get_zone(self, r, c, rows, cols):
        # Assign cell (r,c) to one of 9 zones in a 3x3 grid
        zr = min(2, (r * 3) // rows)
        zc = min(2, (c * 3) // cols)
        return (zr, zc)

    def _zone_cells(self, zr, zc, rows, cols):
        # Return all (r,c) belonging to this zone
        cells = []
        for r in range(rows):
            for c in range(cols):
                if self._get_zone(r, c, rows, cols) == (zr, zc):
                    cells.append((r, c))
        return cells

    def _is_zone_cleared(self, zr, zc, board):
        rows = board.config.rows
        cols = board.config.cols
        for r, c in self._zone_cells(zr, zc, rows, cols):
            cell = board.grid[r][c]
            if not cell.is_mine and not cell.is_revealed:
                return False
        return True

    def evaluate(self, board, game, action):
        rows = board.config.rows
        cols = board.config.cols

        if self._zone_order is None:
            self._zone_order = self._build_zone_order(rows, cols)
            self._unlocked_up_to = 0

        # Advance unlock index: if all zones up to current are cleared, unlock next
        changed = True
        while changed and self._unlocked_up_to < len(self._zone_order) - 1:
            changed = False
            # Check if all currently unlocked zones are cleared
            all_cleared = all(
                self._is_zone_cleared(self._zone_order[i][0], self._zone_order[i][1], board)
                for i in range(self._unlocked_up_to + 1)
            )
            if all_cleared:
                self._unlocked_up_to += 1
                changed = True

        # Determine which zones are currently locked
        unlocked_zones = set(
            self._zone_order[i] for i in range(self._unlocked_up_to + 1)
        )

        # Check: did the player just reveal a cell in a locked zone?
        newly_revealed = action.get('newly_revealed', [])
        if newly_revealed:
            for r, c in newly_revealed:
                z = self._get_zone(r, c, rows, cols)
                if z not in unlocked_zones:
                    return 'lost'

        # Check: did player flag a cell in a locked zone? Treat as loss too.
        act = action.get('action', '')
        if act == 'flag':
            coords = action.get('coords', None)
            if coords is not None:
                r, c = coords
                z = self._get_zone(r, c, rows, cols)
                if z not in unlocked_zones:
                    return 'lost'

        # Win condition: all 9 zones cleared
        if self._unlocked_up_to == len(self._zone_order) - 1:
            all_done = all(
                self._is_zone_cleared(zr, zc, board)
                for zr, zc in self._zone_order
            )
            if all_done:
                return 'won'

        return None

