class RippleReveal(RevealStrategy):
    """
    Cascade reveal that propagates in expanding rings with a twist:
    odd-distance rings from the click reveal normally, but even-distance rings
    only reveal cells if they have adjacent_mines == 0 (i.e. they must also be
    'blank' to continue the flood). This creates a ripple pattern where the
    cascade alternates between full-reveal rings and blank-only rings, leaving
    numbered cells at even distances as hidden gaps that a skilled solver must
    deduce from the partial clue islands, while random play loses the broad
    information a normal cascade would provide.
    """

    def reveal(self, board: Board, r: int, c: int) -> list[tuple[int, int]]:
        start_cell = board.grid[r][c]
        if start_cell.is_mine or start_cell.is_flagged:
            return []

        # BFS tracking distance (ring) from origin
        visited = {(r, c): 0}
        queue = deque([(r, c, 0)])
        revealed = []

        while queue:
            cr, cc, dist = queue.popleft()
            cell = board.grid[cr][cc]

            if cell.is_mine or cell.is_flagged:
                continue

            # Decide whether to reveal this cell based on ring parity
            # Odd distance: always reveal (if not mine/flagged)
            # Even distance (including 0): reveal only if adjacent_mines == 0
            if dist == 0:
                # Always reveal the clicked cell
                if not cell.is_revealed:
                    cell.is_revealed = True
                    revealed.append((cr, cc))
            elif dist % 2 == 1:
                # Odd ring: reveal regardless of count
                if not cell.is_revealed:
                    cell.is_revealed = True
                    revealed.append((cr, cc))
            else:
                # Even ring: only reveal if blank (adjacent_mines == 0)
                if cell.adjacent_mines != 0:
                    continue  # Leave numbered even-ring cells hidden
                if not cell.is_revealed:
                    cell.is_revealed = True
                    revealed.append((cr, cc))

            # Propagate BFS only from cells that were revealed AND are blank
            # (adjacent_mines == 0) — numbered cells stop the cascade
            if cell.adjacent_mines == 0:
                for nr, nc in board.neighbors(cr, cc):
                    if (nr, nc) not in visited:
                        visited[(nr, nc)] = dist + 1
                        queue.append((nr, nc, dist + 1))

        return revealed

