class DriftingMinesPAFGAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def action_priority(self, game, grid, rows, cols):
        return "flag-first"

    def clue_value(self, game, grid, r, c):
        cell = grid[r][c]
        if not cell.is_revealed:
            return None
        raw = cell.adjacent_mines
        if raw is None:
            return None
        neighbors = game.board.neighbors(r, c)
        flagged = sum(1 for nr, nc in neighbors if grid[nr][nc].is_flagged)
        unrevealed = sum(1 for nr, nc in neighbors if not grid[nr][nc].is_revealed and not grid[nr][nc].is_flagged)
        effective = raw - flagged
        if effective < 0:
            effective = 0
        if effective > unrevealed:
            effective = unrevealed
        return effective

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        revealed_positions = set()
        for r in range(rows):
            for c in range(cols):
                if grid[r][c].is_revealed:
                    revealed_positions.add((r, c))
        drift_boost_cells = set()
        for r, c in revealed_positions:
            for nr, nc in game.board.neighbors(r, c):
                cell = grid[nr][nc]
                if not cell.is_revealed and not cell.is_flagged and (nr, nc) not in mine_set:
                    drift_boost_cells.add((nr, nc))
        if not drift_boost_cells:
            return prob_map
        total_unrevealed = sum(
            1 for r in range(rows) for c in range(cols)
            if not grid[r][c].is_revealed and not grid[r][c].is_flagged and (r, c) not in mine_set
        )
        if total_unrevealed == 0:
            return prob_map
        drift_factor = Fraction(3, 10)
        new_map = dict(prob_map)
        for pos in drift_boost_cells:
            if pos in new_map:
                old = new_map[pos]
                boosted = old + (1 - old) * drift_factor
                new_map[pos] = min(boosted, Fraction(19, 20))
            else:
                new_map[pos] = drift_factor
        return new_map

class PerimeterPinningPAFGAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
