class RippleRevealPAFGAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def opening_action(self, game, grid, rows, cols):
        mid_r = rows // 2
        mid_c = cols // 2
        return ('reveal', mid_r, mid_c)

    def clue_value(self, game, grid, r, c):
        cell = grid[r][c]
        if not cell.is_revealed:
            return None
        raw = cell.adjacent_mines
        if raw is None:
            return None
        flagged = sum(
            1 for nr, nc in game.board.neighbors(r, c)
            if grid[nr][nc].is_flagged
        )
        return raw - flagged

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = game.get_config().rows
        cols = game.get_config().cols

        gap_cells = set()
        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                if cell.is_revealed or cell.is_flagged or cell.is_mine:
                    continue
                neighbors = game.board.neighbors(r, c)
                has_revealed_neighbor = any(
                    grid[nr][nc].is_revealed for nr, nc in neighbors
                )
                if not has_revealed_neighbor:
                    continue
                two_hop_revealed = False
                for nr, nc in neighbors:
                    if grid[nr][nc].is_revealed:
                        continue
                    if grid[nr][nc].is_flagged:
                        continue
                    for nnr, nnc in game.board.neighbors(nr, nc):
                        if grid[nnr][nnc].is_revealed:
                            two_hop_revealed = True
                            break
                    if two_hop_revealed:
                        break
                if two_hop_revealed:
                    gap_cells.add((r, c))

        if not gap_cells:
            return prob_map

        total_unrevealed = sum(
            1 for r in range(rows) for c in range(cols)
            if not grid[r][c].is_revealed and not grid[r][c].is_flagged
        )
        total_mines_left = game.get_config().mine_count - sum(
            1 for r in range(rows) for c in range(cols)
            if grid[r][c].is_flagged
        )

        if total_unrevealed <= 0:
            return prob_map

        base_prob = total_mines_left / total_unrevealed

        new_prob_map = dict(prob_map)

        for pos in gap_cells:
            if pos not in new_prob_map:
                r, c = pos
                constraint_probs = []
                for nr, nc in game.board.neighbors(r, c):
                    ncell = grid[nr][nc]
                    if ncell.is_revealed:
                        clue = self.clue_value(game, grid, nr, nc)
                        if clue is not None and clue >= 0:
                            unrevealed_neighbors = [
                                (nnr, nnc) for nnr, nnc in game.board.neighbors(nr, nc)
                                if not grid[nnr][nnc].is_revealed and not grid[nnr][nnc].is_flagged
                            ]
                            if unrevealed_neighbors:
                                local_p = min(1.0, clue / len(unrevealed_neighbors))
                                constraint_probs.append(local_p)
                if constraint_probs:
                    new_prob_map[pos] = sum(constraint_probs) / len(constraint_probs)
                else:
                    new_prob_map[pos] = base_prob
            else:
                r, c = pos
                constraint_probs = []
                for nr, nc in game.board.neighbors(r, c):
                    ncell = grid[nr][nc]
                    if ncell.is_revealed:
                        clue = self.clue_value(game, grid, nr, nc)
                        if clue is not None and clue >= 0:
                            unrevealed_neighbors = [
                                (nnr, nnc) for nnr, nnc in game.board.neighbors(nr, nc)
                                if not grid[nnr][nnc].is_revealed and not grid[nnr][nnc].is_flagged
                            ]
                            if unrevealed_neighbors:
                                local_p = min(1.0, clue / len(unrevealed_neighbors))
                                constraint_probs.append(local_p)
                if constraint_probs:
                    blended = 0.6 * prob_map[pos] + 0.4 * (sum(constraint_probs) / len(constraint_probs))
                    new_prob_map[pos] = blended

        return new_prob_map

