            return displayed
        known_sum = 0
        all_known = True
        for nr, nc in revealed_neighbors:
            nb = game.get_cell(nr, nc)
            nb_val = nb.adjacent_mines
            known_sum += nb_val
        expected_mod = known_sum % 5
        if displayed == expected_mod:
